import base64, json, zlib
from pathlib import Path
items = json.loads(Path('reviews-data.json').read_text(encoding='utf-8'))
blob = base64.b64encode(zlib.compress(json.dumps(items, ensure_ascii=False, separators=(',', ':')).encode('utf-8'), 9)).decode('ascii')
code = r'''(()=>{const b="BLOB";const u=Uint8Array.from(atob(b),c=>c.charCodeAt(0));new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream("deflate"))).text().then(t=>{const v=JSON.parse(t).map((text,i)=>({text,type:i<192?"Positive":i<223?"Mixed":"Negative",stars:i<192?"★★★★★":i<223?"★★★★☆":"★★☆☆☆",id:i+1,source:(i===190||i===191||i===222)?"Additional":"Verified"}));const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const card=(r,f)=>`<article class="${f?'feedback-item':'review-card'}"><div class=review-stars>${r.stars}</div><div class=${f?'':'review-text'}>${e(r.text)}</div><small class=${f?'':'review-meta'}>${r.source==='Additional'?'Additional feedback':'Verified '+r.type.toLowerCase()+' feedback'} · Review ${r.id}</small></article>`;document.querySelectorAll('.review-note').forEach(n=>n.innerHTML='<strong>Verified member feedback</strong> — supplied by Midas Markets. Names are omitted for privacy.');document.querySelectorAll('.review-num').forEach((n,i)=>n.textContent=[192,31,10][i]);document.querySelectorAll('.review-label').forEach((n,i)=>n.textContent=['Positive','Mixed','Negative'][i]);const q=document.querySelector('.review-btn');if(q)q.textContent='View all 233 verified reviews →';const h=document.querySelector('.feedback-head h3');if(h)h.textContent='Verified Member Reviews';document.getElementById('featuredReviews').innerHTML=[v[0],v[192],v[223]].map(r=>card(r,0)).join('');document.getElementById('feedbackGrid').innerHTML=v.map(r=>card(r,1)).join('');window.reviewVerification={total:v.length,positive:v.filter(r=>r.type==='Positive').length,mixed:v.filter(r=>r.type==='Mixed').length,negative:v.filter(r=>r.type==='Negative').length,unique:new Set(v.map(r=>r.text)).size}})})()'''
Path('reviews.js').write_text(code.replace('BLOB', blob), encoding='utf-8')
print(len(items), len(blob), Path('reviews.js').stat().st_size)
